SELECT 
FROM agent_trace_event
WHERE session_id = #{sessionId}

    AND event_type = #{type}


    AND call_id = #{callId}


    AND step_no = #{step}

ORDER BY seq ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM agent_trace_event
WHERE session_id = #{sessionId}

    AND event_type = #{type}


    AND call_id = #{callId}


    AND step_no = #{step}

SELECT 
FROM agent_trace_event
WHERE session_id = #{sessionId}
  AND seq > #{afterSeq}

    AND event_type = #{type}


    AND call_id = #{callId}


    AND step_no = #{step}

ORDER BY seq ASC
LIMIT #{size}

SELECT 
FROM agent_trace_event
WHERE session_id = #{sessionId}
  AND seq > #{afterSeq}
ORDER BY seq ASC
LIMIT #{size}

SELECT session_id AS sessionId, COUNT(*) AS responseCount, SUM(CASE WHEN JSON_EXTRACT(payload_json, '$.promptTokens') IS NULL OR JSON_TYPE(JSON_EXTRACT(payload_json, '$.promptTokens')) = 'NULL' OR JSON_EXTRACT(payload_json, '$.completionTokens') IS NULL OR JSON_TYPE(JSON_EXTRACT(payload_json, '$.completionTokens')) = 'NULL' THEN 1 ELSE 0 END) AS missingUsageCount, SUM(CASE WHEN JSON_EXTRACT(payload_json, '$.model') IS NULL OR JSON_TYPE(JSON_EXTRACT(payload_json, '$.model')) = 'NULL' THEN 1 ELSE 0 END) AS missingModelCount, COUNT(DISTINCT JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.model'))) AS modelCount, MAX(JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.model'))) AS model FROM agent_trace_event WHERE event_type = 'llm/response' AND session_id IN
#{id}
GROUP BY session_id

SELECT COALESCE(MAX(turn_no), 0)
FROM agent_trace_event
WHERE session_id = #{sessionId}
